+static bool ReadFileToBuffer (const char* fileName, BufferedData& buf) {
+  std::ifstream file (fileName, std::ios::in | std::ios::binary);
+  if (!file.is_open())
+    return false;
+  char b;
+  for (;;) {
+    file.read (&b, 1);
+    if (file.gcount() != 1) // end of file
+      break;
+    if (!buf.PushBack (b))
+      return false;
+  }
+  return true;
+}
